const SENTINEL = "<!doctype html>\n<html lang=\"en\" data-theme=\"dark\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"description\" content=\"Sentinel by Aftergraph — verified code review. PRs into merge-ready verdicts on the exact commit.\">\n<title>Sentinel — Verified Code Review · Aftergraph</title>\n<link rel=\"icon\" href=\"data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'><rect width='32' height='32' rx='6' fill='%23080c14'/><path d='M16 5l9 5v12l-9 5-9-5V10z' fill='none' stroke='%2342c7e8' stroke-width='2'/></svg>\">\n<link rel=\"icon\" type=\"image/svg+xml\" href=\"/favicon.ico\">\n<meta property=\"og:site_name\" content=\"Aftergraph\">\n<meta property=\"og:title\" content=\"Sentinel — Verified Code Review\">\n<meta property=\"og:description\" content=\"PRs into merge-ready verdicts on the exact commit.\">\n<meta property=\"og:type\" content=\"website\">\n<meta property=\"og:url\" content=\"https://aftergraph.org/sentinel\">\n</head>\n<style>\n:root{color-scheme:dark}\n*{box-sizing:border-box}\nhtml,body{margin:0;padding:0}\nbody{background:#0a0c12;color:#f2f4f8;font-family:Inter,\"SF Pro Display\",-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,sans-serif;-webkit-font-smoothing:antialiased;line-height:1.6}\na{color:#42c7e8;text-decoration:none}\na:hover{color:#8fe0f5}\n.nav{position:sticky;top:0;z-index:50;display:flex;align-items:center;justify-content:space-between;padding:16px 40px;background:rgba(10,12,18,.82);backdrop-filter:blur(10px);border-bottom:1px solid rgba(255,255,255,.05)}\n.nav .brand{font-weight:600;letter-spacing:.02em;font-size:15px;color:#f2f4f8}\n.nav .brand i{font-style:normal;color:#42c7e8}\n.nav .links{display:flex;align-items:center;gap:28px}\n.nav .links a{color:#9aa3b2;font-size:14px;font-weight:500}\n.nav .links a:hover{color:#f2f4f8}\n.nav .links .cta{background:#42c7e8;color:#0a0c12!important;padding:7px 16px;border-radius:6px;font-weight:600}\n.nav .links .cta:hover{background:#64d5f0;color:#0a0c12!important}\n.hero{max-width:1180px;margin:0 auto;padding:110px 40px 64px;display:grid;grid-template-columns:minmax(0,1.02fr) minmax(0,.98fr);gap:56px;align-items:center}\n.hero h1{font-size:64px;line-height:1.02;letter-spacing:-1.6px;font-weight:500;margin:0 0 22px;max-width:900px;color:#f2f4f8}\n.hero h1 em{font-style:normal;color:#24c4ad}\n.hero .lede{font-size:19px;line-height:1.6;color:#9aa3b2;max-width:640px;margin:0 0 36px;font-weight:400}\n.trust{font-size:13px;color:#7b8494;margin:22px 0 0;max-width:640px}\n.prcard{min-width:0;border:1px solid rgba(255,255,255,.08);border-radius:12px;background:#0d111b;padding:26px;box-shadow:0 24px 80px rgba(0,0,0,.45)}\n.prcard-head{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;margin-bottom:18px}\n.prcard-kicker{margin:0 0 8px;font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:#42c7e8;font-weight:600}\n.prcard-title{margin:0 0 6px;font-size:17px;font-weight:600;color:#f2f4f8}\n.prcard-title span{display:block;font-size:13px;font-weight:400;color:#9aa3b2;margin-top:2px}\n.prcard-sha{margin:0;font-size:12px;color:#7b8494}\n.prcard-sha code{font-family:\"JetBrains Mono\",ui-monospace,Menlo,monospace;color:#42c7e8;font-size:12px}\n.verdict{flex:none;display:inline-flex;align-items:center;gap:8px;margin:0;padding:7px 12px;border-radius:999px;font-size:11px;font-weight:700;letter-spacing:.08em;background:rgba(255,125,140,.12);border:1px solid rgba(255,125,140,.45);color:#ff7d8c;white-space:nowrap}\n.prcard-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:0 0 18px}\n.prcard-stats div{border:1px solid rgba(255,255,255,.06);border-radius:8px;padding:10px 12px;background:rgba(255,255,255,.015)}\n.prcard-stats dt{font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:#7b8494;margin-bottom:2px}\n.prcard-stats dd{margin:0;font-size:22px;font-weight:600;color:#f2f4f8}\n.finding{border:1px solid rgba(255,125,140,.3);border-left:3px solid #ff7d8c;border-radius:8px;padding:12px 14px;margin:0 0 18px;background:rgba(255,125,140,.04)}\n.finding-title{margin:0 0 10px;font-size:14px;font-weight:600;color:#f2f4f8}\n.sev{display:inline-block;margin-right:8px;padding:2px 8px;border-radius:999px;font-size:10px;font-weight:700;letter-spacing:.07em;background:rgba(255,125,140,.14);border:1px solid rgba(255,125,140,.4);color:#ff7d8c;vertical-align:1px}\n.ticks{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:8px 18px}\n.ticks li{font-size:13px;color:#9aa3b2}\n.ticks li b{color:#24c4ad;font-weight:700;margin-right:6px}\n.pipeline{list-style:none;margin:0 0 20px;padding:0;display:flex;flex-wrap:wrap;gap:6px;align-items:center}\n.pipeline li{font-size:11px;font-weight:600;letter-spacing:.04em;padding:5px 10px;border-radius:999px;border:1px solid rgba(255,255,255,.1);color:#7b8494;animation:pstep 10s linear infinite}\n.pipeline li:nth-child(2){animation-delay:2s}\n.pipeline li:nth-child(3){animation-delay:4s}\n.pipeline li:nth-child(4){animation-delay:6s}\n.pipeline li.done{animation-delay:8s;border-color:rgba(255,125,140,.5);color:#ff7d8c}\n@keyframes pstep{0%,18%{border-color:rgba(66,199,232,.7);color:#f2f4f8;background:rgba(66,199,232,.08)}20%,100%{border-color:rgba(255,255,255,.1);color:#7b8494;background:transparent}}\n.pipeline li.done{animation-name:pstep-done}\n@keyframes pstep-done{0%,18%{border-color:rgba(255,125,140,.7);color:#ff7d8c;background:rgba(255,125,140,.08)}20%,100%{border-color:rgba(255,125,140,.5);color:#ff7d8c;background:transparent}}\n.card-actions .btn{padding:9px 18px;font-size:14px}\n.cta-row{display:flex;gap:14px;flex-wrap:wrap}\n.btn{display:inline-block;padding:10px 20px;border-radius:6px;font-size:15px;font-weight:600;transition:all .18s}\n.btn-p{background:#42c7e8;color:#0a0c12}\n.btn-p:hover{background:#64d5f0;color:#0a0c12}\n.btn-g{background:rgba(255,255,255,.02);border:1px solid rgba(255,255,255,.08);color:#d7dbe2}\n.btn-g:hover{border-color:rgba(66,199,232,.4);color:#42c7e8}\n.section{max-width:1180px;margin:0 auto;padding:88px 40px}\n.stitle{font-size:13px;letter-spacing:.14em;text-transform:uppercase;color:#42c7e8;font-weight:500;margin:0 0 14px}\n.sh2{font-size:44px;line-height:1.06;letter-spacing:-1.1px;font-weight:500;margin:0 0 18px;color:#f2f4f8}\n.slede{font-size:17px;color:#9aa3b2;max-width:620px;margin:0 0 44px}\n.chain{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin:6px 0 8px}\n.chain .node{border:1px solid rgba(66,199,232,.35);border-radius:6px;padding:7px 14px;font-size:14px;color:#d7dbe2;background:rgba(66,199,232,.05);font-weight:500}\n.chain .arr{color:#42c7e8;font-size:17px}\n.grid{border-top:1px solid rgba(255,255,255,.05);padding-top:18px;display:grid;grid-template-columns:repeat(auto-fill,minmax(330px,1fr));gap:14px;margin-top:18px}\n.card-p{border:1px solid rgba(255,255,255,.06);background:rgba(255,255,255,.015);border-radius:12px;padding:24px;display:flex;flex-direction:column;gap:10px}\n.card-p h3{font-size:19px;margin:0;font-weight:600;letter-spacing:-.2px;color:#f2f4f8;display:flex;align-items:center;flex-wrap:wrap;gap:10px}\n.card-p p{font-size:14px;line-height:1.6;color:#9aa3b2;margin:0}\n.card-p .go{margin-top:auto;padding-top:14px}\n.badge{display:inline-block;padding:3px 9px;border-radius:999px;font-size:10px;font-weight:600;letter-spacing:.07em;text-transform:uppercase}\n.b-pr{background:rgba(240,166,74,.14);color:#f0a64a;border:1px solid rgba(240,166,74,.3)}\n.code{background:#0e1220;border:1px solid rgba(255,255,255,.06);border-radius:12px;padding:22px;font-family:\"JetBrains Mono\",ui-monospace,SFMono-Regular,Menlo,monospace;font-size:13px;color:#b6c2d4;overflow-x:auto}\n.code .c{color:#5d6878}.code .k{color:#ff7d8c}.code .f{color:#42c7e8}.code .g{color:#24c4ad}\n.ev{border:1px solid rgba(36,196,173,.28);background:rgba(36,196,173,.04);border-radius:10px;padding:14px 18px;font-size:13px;color:#86c9be;margin-top:44px}\n.foot{max-width:1180px;margin:0 auto;padding:56px 40px 88px;border-top:1px solid rgba(255,255,255,.05);display:flex;flex-wrap:wrap;gap:40px}\n.foot .col{min-width:150px}\n.foot h4{font-size:12px;letter-spacing:.1em;text-transform:uppercase;color:#7b8494;margin:0 0 14px;font-weight:600}\n.foot a{display:block;color:#9aa3b2;font-size:14px;margin-bottom:9px}\n.foot a:hover{color:#f2f4f8}\n@media(max-width:900px){.hero{grid-template-columns:1fr;gap:40px;padding-top:72px}.hero h1{font-size:44px}.sh2{font-size:34px}.nav .links a:not(.cta){display:none}.hero,.section{padding-left:22px;padding-right:22px}}\n@media(max-width:480px){.hero{padding-top:56px}.hero h1{font-size:40px;letter-spacing:-1px}.hero .lede{font-size:17px}.prcard{padding:18px}.prcard-head{flex-direction:column}.prcard-stats{grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.prcard-stats dd{font-size:18px}.nav{padding:14px 22px}}\n@media (prefers-reduced-motion: reduce){*{transition:none!important}.pipeline li{animation:none}.pipeline li.done{border-color:rgba(255,125,140,.5);color:#ff7d8c}}\na:focus-visible,button:focus-visible,input:focus-visible{outline:2px solid #42c7e8;outline-offset:2px}\n</style>\n</head>\n<body>\n<nav class=\"nav\">\n<div class=\"brand\">AFTERGRAPH<i>.</i></div>\n<div class=\"links\"><a href=\"/\">Platform</a><a href=\"https://docs.aftergraph.org/sentinel/\" target=\"_blank\" rel=\"noopener\">Docs ↗</a><a href=\"https://github.com/Aftergraph/sentinel\">Repository</a><a href=\"/launch\" class=\"cta\">Launch</a></div>\n</nav>\n\n<header class=\"hero\">\n<div>\n<h1>Ship code you can <em>prove</em> works</h1>\n<p class=\"lede\">Sentinel reviews, tests and verifies every change against the exact commit you intend to merge.</p>\n<div class=\"cta-row\">\n<a class=\"btn btn-p\" href=\"https://github.com/Aftergraph/sentinel\">Start free</a>\n<a class=\"btn btn-g\" href=\"#verdict\">See a verified PR</a>\n<a class=\"btn btn-g\" href=\"https://docs.aftergraph.org/sentinel/\" target=\"_blank\" rel=\"noopener\">Read the docs ↗</a>\n</div>\n<p class=\"trust\">No training on your private code. Cloud or self-hosted.</p>\n</div>\n<aside class=\"prcard\" aria-label=\"Example live pull request verdict\">\n<div class=\"prcard-head\">\n<div>\n<p class=\"prcard-kicker\">Live PR · example</p>\n<p class=\"prcard-title\">PR #482 <span>feat: session token rotation</span></p>\n<p class=\"prcard-sha\">HEAD <code>98af672</code></p>\n</div>\n<p class=\"verdict\" role=\"status\"><span aria-hidden=\"true\">■</span> DO_NOT_SHIP</p>\n</div>\n<dl class=\"prcard-stats\">\n<div><dt>Blockers</dt><dd>2</dd></div>\n<div><dt>Checks</dt><dd>18</dd></div>\n<div><dt>Evidence</dt><dd>11</dd></div>\n</dl>\n<div class=\"finding\">\n<p class=\"finding-title\"><span class=\"sev\">HIGH</span> Session token accepted after rotation</p>\n<ul class=\"ticks\">\n<li><b>✓</b> reproduced</li>\n<li><b>✓</b> regression test</li>\n<li><b>✓</b> API captured</li>\n</ul>\n</div>\n<ol class=\"pipeline\" aria-label=\"Verification pipeline: analyzing, finding, reproducing, evidence, verdict\">\n<li>Analyzing</li>\n<li>Finding</li>\n<li>Reproducing</li>\n<li>Evidence</li>\n<li class=\"done\">Verdict</li>\n</ol>\n<div class=\"cta-row card-actions\">\n<a class=\"btn btn-p\" href=\"#verdict\">View evidence</a>\n<a class=\"btn btn-g\" href=\"https://docs.aftergraph.org/sentinel/\" target=\"_blank\" rel=\"noopener\">Fix</a>\n</div>\n</aside>\n</header>\n\n<section class=\"section\" id=\"verdict\">\n<div class=\"stitle\">Actual output · rule-pack 1.1.0</div>\n<h2 class=\"sh2\">A verdict, not a comment</h2>\n<p class=\"slede\">This is what Sentinel prints. One decision, bound to one commit, every finding anchored to a file and line.</p>\n<div class=\"code\"><span class=\"c\"># sentinel review --pr 42 — exit 1</span>\nHEAD <span class=\"f\">a3f9c1d</span> (verified: base main@9be201c unchanged since review start)\n\n<span class=\"k\">DO NOT SHIP</span> — 2 findings\n1. [security] Unauthenticated DELETE route — <span class=\"f\">routes/admin.mjs:41</span>\n   Rule: auth-required-routes. Evidence: no auth middleware on DELETE /admin/purge.\n2. [reliability] Migration without rollback — <span class=\"f\">db/migrate_014.sql</span>\n   Rule: migration-rollback-required. Evidence: no DOWN block.\n\n<span class=\"g\">4 checks passed</span>: secrets-scan, lockfile-consistency, test-status, diff-size.</div>\n<div class=\"ev\">Maturity: <b>prototype</b> — CLI v0.1 ships free for public repos. The GitHub App, sandbox verification runners and signed receipts are roadmap, not product. Nothing here claims otherwise.</div>\n</section>\n\n<section class=\"section\" id=\"how\">\n<div class=\"stitle\">How it works</div>\n<h2 class=\"sh2\">Reviewed is not verified</h2>\n<p class=\"slede\">Review finds what looks wrong. Verification proves what holds. Only both together earn a verdict — always on the exact HEAD.</p>\n<div class=\"chain\">\n<span class=\"node\">Change</span><span class=\"arr\">→</span><span class=\"node\">Review</span><span class=\"arr\">→</span><span class=\"node\">Findings</span><span class=\"arr\">→</span><span class=\"node\">Verification</span><span class=\"arr\">→</span><span class=\"node\">Evidence</span><span class=\"arr\">→</span><span class=\"node\">Verdict</span>\n</div>\n<div class=\"grid\">\n<div class=\"card-p\"><h3>Exact-head binding</h3><p>Every verdict names the commit it verified. A new push invalidates it — exit 2 STALE, never a silent approval of moved code.</p></div>\n<div class=\"card-p\"><h3>Deterministic rules</h3><p>20-rule pack, versioned and pinned. Same diff plus same pack gives the byte-identical verdict — reproducible in audits.</p></div>\n<div class=\"card-p\"><h3>Machine surfaces</h3><p>Human, JSON, SARIF 2.1.0 and governance verdict formats. Exit codes gate CI: 0 pass, 1 fail, 2 re-run.</p></div>\n</div>\n</section>\n\n<section class=\"section\" id=\"trust\">\n<div class=\"stitle\">Trust</div>\n<h2 class=\"sh2\">Read-only by construction</h2>\n<p class=\"slede\">The CLI performs zero writes: no comments, no checks, no commits, no account. Verdicts go to stdout and a local receipt ledger you own.</p>\n<div class=\"code\"><span class=\"c\"># local-first: no GitHub needed</span>\ngit diff | sentinel review --diff - --repo myorg/myrepo</div>\n</section>\n\n<footer class=\"foot\">\n<div class=\"col\"><h4>Sentinel</h4><a href=\"https://github.com/Aftergraph/sentinel\">Repository</a><a href=\"https://docs.aftergraph.org/sentinel/\" target=\"_blank\" rel=\"noopener\">Docs ↗</a><a href=\"/launch\">Launcher</a></div>\n<div class=\"col\"><h4>Aftergraph</h4><a href=\"/\">Platform</a><a href=\"/status\">Status</a><a href=\"https://github.com/Aftergraph\">GitHub</a></div>\n<div class=\"col\"><h4>Meta</h4><a href=\"https://github.com/Aftergraph/aftergraph.org\">This site's source</a><a href=\"/healthz\">Health</a></div>\n</footer>\n</body>\n</html>\n";
const HEALTH = "{\"status\":\"ok\",\"deployed\":\"build-time\",\"route\":\"aftergraph-site v1.2.0\",\"sha\":\"local\"}";
const ROBOTS = "User-agent: *\nAllow: /\nDisallow: /healthz\n\n# Aftergraph allows responsible AI training crawlers that honor robots.txt.\nUser-agent: GPTBot\nAllow: /\nUser-agent: ClaudeBot\nAllow: /\nUser-agent: Google-Extended\nAllow: /\n\nSitemap: https://aftergraph.org/sitemap.xml\n";
const SITEMAP = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">\n  <url><loc>https://aftergraph.org/</loc><changefreq>weekly</changefreq><priority>1.0</priority></url>\n  <url><loc>https://aftergraph.org/launch</loc><changefreq>weekly</changefreq><priority>0.8</priority></url>\n  <url><loc>https://aftergraph.org/status</loc><changefreq>daily</changefreq><priority>0.7</priority></url>\n  <url><loc>https://aftergraph.org/sentinel</loc><changefreq>weekly</changefreq><priority>0.9</priority></url>\n</urlset>\n";
addEventListener('fetch', event => {
  const url = new URL(event.request.url);
  const p = url.pathname;
  let body;
  let contentType = 'text/html;charset=utf-8';
  let cache = 'public, max-age=300';
  let responseStatus = 200;
  if (p === '/healthz' || p === '/health') { body = HEALTH; contentType = 'application/json'; cache = 'public, max-age=60'; }
  else if (p === '/robots.txt') { body = ROBOTS; contentType = 'text/plain;charset=utf-8'; cache = 'public, max-age=3600'; }
  else if (p === '/sitemap.xml') { body = SITEMAP; contentType = 'application/xml;charset=utf-8'; cache = 'public, max-age=3600'; }
  else if (p === '/llms.txt') { body = LLMS; contentType = 'text/plain;charset=utf-8'; cache = 'public, max-age=3600'; }
  else if (p === '/.well-known/security.txt') { body = SECURITY; contentType = 'text/plain;charset=utf-8'; cache = 'public, max-age=3600'; }
  else if (p === '/favicon.ico' || p === '/og-image.svg') { body = MONOGRAM; contentType = 'image/svg+xml;charset=utf-8'; cache = 'public, max-age=86400'; }
  else if (p === '/launch' || p === '/launch/') { body = LAUNCH; }
  else if (p === '/status' || p === '/status/') { body = STATUS; }
  else if (p === '/sentinel' || p === '/sentinel/') { body = SENTINEL; }
  else if (p === '/404') { body = NOTFOUND; }
  else if (p === '/') { body = LANDING; }
  else { body = NOTFOUND; responseStatus = 404; cache = 'no-store'; }
  event.respondWith(new Response(body, {
    status: responseStatus,
    headers: { 'content-type': contentType, 'cache-control': cache, ...SECURE }
  }));
});